package glitch

import data.glitch_lib

is_weak_hash_value(v) {
    v.ir_type == "String"
    regex.match("(?i).*(\\bmd5\\b|sha-?1|\\bmd4\\b|\\bmd2\\b|md5_crypt|sha1_crypt).*", v.value)
}

is_weak_cipher_value(v) {
    v.ir_type == "String"
    regex.match("(?i).*(\\bDES\\b|3DES|TDEA|\\bRC4\\b|\\bRC2\\b|BLOWFISH|CBC_SHA|EXPORT).*", v.value)
}

is_weak_tls_value(v) {
    v.ir_type == "String"
    regex.match("(?i).*(SSLv2|SSLv3|TLSv1\\.0|TLSv1\\.1|TLS_1_0|TLS_1_1|ELBSecurityPolicy-2016-08).*", v.value)
}

is_weak_curve_value(v) {
    v.ir_type == "String"
    regex.match("(?i).*(P-192|P-224|secp192r1|secp224r1|sect163k1).*", v.value)
}

is_weak_key_size(v) {
    v.ir_type == "Integer"
    v.value < 2048
}

is_hash_key(name) { regex.match("(?i).*(hash_algorithm|signing_algorithm|digest_algorithm|certificate_algorithm|encrypt).*", name) }

is_cipher_key(name) { regex.match("(?i).*(encryption_algorithm|cipher_algorithm|server_side_encryption|cipher_suites?|allowed_ciphers|enabled_ciphers|tls_ciphers).*", name) }
is_cipher_key(name) { regex.match("(?i)^(algorithm|cipher)$", name) }

is_tls_key(name) { regex.match("(?i).*(ssl_policy|security_policy|minimum_protocol_version|min_tls_version|tls_version|ssl_version).*", name) }
is_tls_key(name) { regex.match("(?i)^protocol$", name) }

is_curve_key(name) { regex.match("(?i).*(ecdsa_curve|elliptic_curve|curve_name).*", name) }

is_key_size_key(name) { regex.match("(?i).*(key_size|key_length|key_bits|rsa_bits|modulus_length|key_spec).*", name) }

is_weak_for_key(name, value) { is_hash_key(name); is_weak_hash_value(value) }
is_weak_for_key(name, value) { is_cipher_key(name); is_weak_cipher_value(value) }
is_weak_for_key(name, value) { is_tls_key(name); is_weak_tls_value(value) }
is_weak_for_key(name, value) { is_curve_key(name); is_weak_curve_value(value) }
is_weak_for_key(name, value) { is_key_size_key(name); is_weak_key_size(value) }

